+    disable_pager: bool,
+
+    #[arg(value_name = "FILE", help = "File to view")]
+    file: Option<PathBuf>,
+}
+
+#[derive(Clone, Debug)]
+struct TableData {
+    header: Option<Vec<String>>,
+    rows: Vec<Vec<String>>,
+}
+
+#[derive(Clone, Copy)]
+struct BorderSpec {
+    left: &'static str,
+    join: &'static str,
+    right: &'static str,
+    fill: char,
+}
+
+#[derive(Clone, Copy)]
+struct RowSpec {
+    left: &'static str,
+    join: &'static str,
+    right: &'static str,
+}
+
+#[derive(Clone, Copy)]
+struct StyleSpec {
+    row: RowSpec,
+    top: Option<BorderSpec>,
+    header_sep: Option<BorderSpec>,
+    row_sep: Option<BorderSpec>,
+    bottom: Option<BorderSpec>,
+}
+
+fn main() {
+    if let Err(err) = run() {
+        eprintln!("csview: {err}");
+        std::process::exit(1);
+    }
+}
+
+fn run() -> Result<(), Box<dyn Error>> {
+    let args = Args::parse();
+    let mut table = if let Some(path) = &args.file {
+        let file = File::open(path)?;
+        read_table(file, &args)?
+    } else {
+        read_table(io::stdin().lock(), &args)?
+    };
+
+    if args.number {
+        add_numbers(&mut table);
+    }
+
+    let output = render_table(&table, &args);
+    write_output(&output, args.disable_pager)?;
+    Ok(())
+}
+
+fn read_table<R: Read>(reader: R, args: &Args) -> Result<TableData, Box<dyn Error>> {
+    let delimiter = if args.tsv { b'\t' } else { args.delimiter as u8 };
+    let mut csv = ReaderBuilder::new()
+        .delimiter(delimiter)
+        .has_headers(!args.no_headers)
+        .from_reader(reader);
+
+    let header = if args.no_headers {
+        None
+    } else {
+        Some(csv.headers()?.iter().map(str::to_owned).collect())
+    };
+
+    let mut rows = Vec::new();
+    for record in csv.records() {
+        let record = record?;
+        rows.push(record.iter().map(str::to_owned).collect());
+    }
+
+    Ok(TableData { header, rows })
+}
+
+fn add_numbers(table: &mut TableData) {
+    if let Some(header) = &mut table.header {
+        header.insert(0, "#".to_owned());
+    }
+
+    for (idx, row) in table.rows.iter_mut().enumerate() {
+        row.insert(0, (idx + 1).to_string());
+    }
+}
+
+fn render_table(table: &TableData, args: &Args) -> String {
+    let style = style_spec(args.style);
+    let widths = sniff_widths(table, args);
+    let mut out = String::new();
+
+    if let Some(border) = style.top {
+        out.push_str(&render_border(border, &widths, args.padding, args.indent));
+    }
+
+    if let Some(header) = &table.header {
+        out.push_str(&render_row(
+            &style.row,
+            header,
+            &widths,
+            args.padding,
+            args.indent,
+            args.header_align,
+        ));
+    }
+
+    if table.header.is_some() && !table.rows.is_empty() {
+        if let Some(border) = style.header_sep {
+            out.push_str(&render_border(border, &widths, args.padding, args.indent));
+        }
+    }
+
+    for (idx, row) in table.rows.iter().enumerate() {
+        out.push_str(&render_row(
+            &style.row,
+            row,
+            &widths,
+            args.padding,
+            args.indent,
+            args.body_align,
+        ));
+
+        if idx + 1 != table.rows.len() {
+            if let Some(border) = style.row_sep {
+                out.push_str(&render_border(border, &widths, args.padding, args.indent));
+            }
+        }
+    }
+
+    if let Some(border) = style.bottom {
+        out.push_str(&render_border(border, &widths, args.padding, args.indent));
+    }
+
+    out
+}
+
+fn sniff_widths(table: &TableData, args: &Args) -> Vec<usize> {
+    let mut widths = match &table.header {
+        Some(header) => header.iter().map(|cell| display_width(cell)).collect::<Vec<_>>(),
+        None => table
+            .rows
+            .first()
+            .map(|row| vec![0; row.len()])
+            .unwrap_or_default(),
+    };
+
+    let sniff_limit = if args.sniff == 0 {
+        table.rows.len()
+    } else {
+        table.rows.len().min(args.sniff)
+    };
+
+    for row in table.rows.iter().take(sniff_limit) {
+        if widths.len() < row.len() {
+            widths.resize(row.len(), 0);
+        }
+        for (idx, cell) in row.iter().enumerate() {
+            widths[idx] = widths[idx].max(display_width(cell));
+        }
+    }
+
+    if args.number && table.header.is_none() && table.rows.is_empty() {
+        widths = vec![1];
+    }
+
+    widths
+}
+
+fn render_border(border: BorderSpec, widths: &[usize], padding: usize, indent: usize) -> String {
+    let mut line = String::new();
+    line.push_str(&" ".repeat(indent));
+    line.push_str(border.left);
+
+    if widths.is_empty() {
+        line.push_str(border.right);
+        line.push('\n');
+        return line;
+    }
+
+    for (idx, width) in widths.iter().enumerate() {
+        line.push_str(&border.fill.to_string().repeat(width + (padding * 2)));
+        if idx + 1 != widths.len() {
+            line.push_str(border.join);
+        }
+    }
+
+    line.push_str(border.right);
+    line.push('\n');
+    line
+}
+
+fn render_row(
+    row_spec: &RowSpec,
+    row: &[String],
+    widths: &[usize],
+    padding: usize,
+    indent: usize,
+    align: AlignOpt,
+) -> String {
+    let mut line = String::new();
+    line.push_str(&" ".repeat(indent));
+    line.push_str(row_spec.left);
+
+    if widths.is_empty() {
+        line.push_str(row_spec.right);
+        line.push('\n');
+        return line;
+    }
+
+    for (idx, width) in widths.iter().enumerate() {
+        let cell = row.get(idx).map(String::as_str).unwrap_or("");
+        line.push_str(&render_cell(cell, *width, padding, align));
+        if idx + 1 != widths.len() {
+            line.push_str(row_spec.join);
+        }
+    }
+
+    line.push_str(row_spec.right);
+    line.push('\n');
+    line
+}
+
+fn render_cell(cell: &str, width: usize, padding: usize, align: AlignOpt) -> String {
+    let clipped = truncate_to_width(cell, width);
+    let clipped_width = display_width(&clipped);
+    let spare = width.saturating_sub(clipped_width);
+    let (left_extra, right_extra) = match align {
+        AlignOpt::Left => (0, spare),
+        AlignOpt::Center => (spare / 2, spare - (spare / 2)),
+        AlignOpt::Right => (spare, 0),
+    };
+
+    format!(
+        "{}{}{}{}{}",
+        " ".repeat(padding),
+        " ".repeat(left_extra),
+        clipped,
+        " ".repeat(right_extra),
+        " ".repeat(padding)
+    )
+}
+
+fn truncate_to_width(cell: &str, max_width: usize) -> String {
+    if max_width == 0 {
+        return String::new();
+    }
+
+    let mut width = 0usize;
+    let mut out = String::new();
+
+    for ch in cell.chars() {
+        let ch_width = char_width(ch);
+        if width + ch_width > max_width {
+            break;
+        }
+        width += ch_width;
+        out.push(ch);
+    }
+
+    out
+}
+
+fn display_width(cell: &str) -> usize {
+    cell.chars().map(char_width).sum()
+}
+
+fn char_width(ch: char) -> usize {
+    UnicodeWidthChar::width(ch).unwrap_or_else(|| if ch.is_control() { 1 } else { 0 })
+}
+
+fn write_output(output: &str, disable_pager: bool) -> Result<(), Box<dyn Error>> {
+    if !disable_pager && io::stdout().is_terminal() {
+        if let Ok(mut child) = Command::new("less")
+            .arg("-SR")
+            .stdin(Stdio::piped())
+            .spawn()
+        {
+            if let Some(mut stdin) = child.stdin.take() {
+                stdin.write_all(output.as_bytes())?;
+            }
+            child.wait()?;
+            return Ok(());
+        }
+    }
+
+    io::stdout().write_all(output.as_bytes())?;
+    Ok(())
+}
+
+fn style_spec(style: StyleOpt) -> StyleSpec {
+    match style {
+        StyleOpt::None => StyleSpec {
+            row: RowSpec {
+                left: "",
+                join: " ",
+                right: "",
+            },
+            top: None,
+            header_sep: None,
+            row_sep: None,
+            bottom: None,
+        },
+        StyleOpt::Ascii => StyleSpec {
