+            }),
+            row_sep: None,
+            bottom: Some(BorderSpec {
+                left: "+",
+                join: "+",
+                right: "+",
+                fill: '-',
+            }),
+        },
+        StyleOpt::Ascii2 => StyleSpec {
+            row: RowSpec {
+                left: " ",
+                join: "|",
+                right: " ",
+            },
+            top: None,
+            header_sep: Some(BorderSpec {
+                left: " ",
+                join: "+",
+                right: " ",
+                fill: '-',
+            }),
+            row_sep: None,
+            bottom: None,
+        },
+        StyleOpt::Sharp => StyleSpec {
+            row: RowSpec {
+                left: "│",
+                join: "│",
+                right: "│",
+            },
+            top: Some(BorderSpec {
+                left: "┌",
