use std::error::Error;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};

use clap::{Parser, ValueEnum};
use csv::ReaderBuilder;
use unicode_width::UnicodeWidthChar;

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum StyleOpt {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum AlignOpt {
    Left,
    Center,
    Right,
}

#[derive(Debug, Parser)]
#[command(about = "A high performance csv viewer with cjk/emoji support.", version = "1.3.4")]
struct Args {
    #[arg(short = 'H', long = "no-headers", help = "Specify that the input has no header row")]
    no_headers: bool,

    #[arg(short = 'n', long = "number", help = "Prepend a column of line numbers to the table")]
    number: bool,

    #[arg(
        short = 't',
        long = "tsv",
        conflicts_with = "delimiter",
        help = "Use '\\t' as delimiter for tsv"
    )]
    tsv: bool,

    #[arg(
        short = 'd',
        long = "delimiter",
        default_value = ",",
        value_name = "DELIMITER",
        value_parser = clap::value_parser!(char),
        conflicts_with = "tsv",
        help = "Specify the field delimiter"
    )]
    delimiter: char,

    #[arg(
        short = 's',
        long = "style",
        default_value = "sharp",
        value_name = "STYLE",
        value_enum,
        ignore_case = true,
        help = "Specify the border style"
    )]
    style: StyleOpt,

    #[arg(
        short = 'p',
        long = "padding",
        default_value_t = 1usize,
        value_name = "PADDING",
        help = "Specify padding for table cell"
    )]
    padding: usize,

    #[arg(
        short = 'i',
        long = "indent",
        default_value_t = 0usize,
        value_name = "INDENT",
        help = "Specify global indent for table"
    )]
    indent: usize,

    #[arg(
        long = "sniff",
        default_value_t = 1000usize,
        value_name = "LIMIT",
        help = "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"
    )]
    sniff: usize,

    #[arg(
        long = "header-align",
        default_value = "center",
        value_name = "HEADER_ALIGN",
        value_enum,
        ignore_case = true,
        help = "Specify the alignment of the table header"
    )]
    header_align: AlignOpt,

    #[arg(
        long = "body-align",
        default_value = "left",
        value_name = "BODY_ALIGN",
        value_enum,
        ignore_case = true,
        help = "Specify the alignment of the table body"
    )]
    body_align: AlignOpt,

    #[arg(short = 'P', long = "disable-pager", help = "Disable pager")]
    disable_pager: bool,

    #[arg(value_name = "FILE", help = "File to view")]
    file: Option<PathBuf>,
}

#[derive(Clone, Debug)]
struct TableData {
    header: Option<Vec<String>>,
    rows: Vec<Vec<String>>,
}

#[derive(Clone, Copy)]
struct BorderSpec {
    left: &'static str,
    join: &'static str,
    right: &'static str,
    fill: char,
}

#[derive(Clone, Copy)]
struct RowSpec {
    left: &'static str,
    join: &'static str,
    right: &'static str,
