    for (idx, width) in widths.iter().enumerate() {
        line.push_str(&border.fill.to_string().repeat(width + (padding * 2)));
        if idx + 1 != widths.len() {
            line.push_str(border.join);
        }
    }

    line.push_str(border.right);
    line.push('\n');
    line
