+    let mut width = 0;
+    let mut out = String::new();
+    for grapheme in UnicodeSegmentation::graphemes(value, true) {
+        let next = grapheme_width(grapheme);
+        if width + next > limit {
+            break;
+        }
+        width += next;
+        out.push_str(grapheme);
+    }
+    out
+}
+
+fn format_cell(value: &str, width: usize, padding: usize, align: Align) -> String {
+    let value = truncate_to_width(value, width);
+    let slack = width.saturating_sub(display_width(&value));
+    let (left_extra, right_extra) = match align {
+        Align::Left => (0, slack),
+        Align::Center => (slack / 2, slack - (slack / 2)),
+        Align::Right => (slack, 0),
+    };
+
+    format!(
+        "{}{}{}{}{}",
+        " ".repeat(padding),
+        " ".repeat(left_extra),
+        value,
+        " ".repeat(right_extra),
+        " ".repeat(padding)
+    )
+}
+
+fn render_row(row: &[String], widths: &[usize], padding: usize, align: Align, style: Style) -> String {
+    let cells = widths
+        .iter()
+        .enumerate()
+        .map(|(idx, width)| {
+            format_cell(row.get(idx).map(String::as_str).unwrap_or(""), *width, padding, align)
+        })
+        .collect::<Vec<_>>();
+
+    let parts = row_style(style);
+    format!("{}{}{}", parts.left, cells.join(parts.center), parts.right)
+}
+
+fn render_rule(widths: &[usize], padding: usize, style: RuleStyle) -> String {
+    let segments = widths
+        .iter()
+        .map(|width| std::iter::repeat(style.fill).take(width + (padding * 2)).collect::<String>())
+        .collect::<Vec<_>>();
+    format!(
+        "{}{}{}",
+        style.left,
+        segments.join(&style.center.to_string()),
+        style.right
+    )
+}
+
+fn write_output(output: &str, disable_pager: bool) -> Result<(), Box<dyn Error>> {
+    if !disable_pager && io::stdout().is_terminal() {
+        if let Ok(mut child) = Command::new("less")
+            .arg("-SR")
+            .stdin(Stdio::piped())
+            .spawn()
+        {
+            if let Some(mut stdin) = child.stdin.take() {
+                stdin.write_all(output.as_bytes())?;
+            }
+            child.wait()?;
+            return Ok(());
+        }
+    }
+
+    io::stdout().write_all(output.as_bytes())?;
+    Ok(())
+}
+
+fn row_style(style: Style) -> RowStyle {
+    match style {
+        Style::None => RowStyle {
+            left: "",
+            center: " ",
+            right: "",
+        },
+        Style::Ascii => RowStyle {
+            left: "|",
+            center: "|",
+            right: "|",
