+            right: " ",
+        },
+        Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => RowStyle {
+            left: "│",
+            center: "│",
+            right: "│",
+        },
+        Style::Markdown => RowStyle {
+            left: "|",
+            center: "|",
+            right: "|",
+        },
+    }
+}
+
+fn top_rule(style: Style) -> Option<RuleStyle> {
+    match style {
+        Style::None | Style::Ascii2 | Style::Markdown => None,
+        Style::Ascii => Some(RuleStyle {
+            left: '+',
+            center: '+',
+            right: '+',
+            fill: '-',
+        }),
+        Style::Sharp | Style::Grid => Some(RuleStyle {
+            left: '┌',
+            center: '┬',
+            right: '┐',
+            fill: '─',
+        }),
+        Style::Rounded => Some(RuleStyle {
+            left: '╭',
