+
+fn middle_rule(style: Style) -> Option<RuleStyle> {
+    match style {
+        Style::None => None,
+        Style::Ascii | Style::Ascii2 => Some(RuleStyle {
+            left: if style == Style::Ascii { '+' } else { ' ' },
