+        }),
+        Style::Markdown => Some(RuleStyle {
+            left: '|',
+            center: '|',
+            right: '|',
+            fill: '-',
+        }),
+    }
+}
+
+fn bottom_rule(style: Style) -> Option<RuleStyle> {
+    match style {
+        Style::None | Style::Ascii2 | Style::Markdown => None,
+        Style::Ascii => Some(RuleStyle {
+            left: '+',
+            center: '+',
+            right: '+',
+            fill: '-',
