#!/usr/bin/env python3

import ctypes
import difflib
import os
import subprocess
import sys
from dataclasses import dataclass
from typing import List, Optional, Sequence, Tuple

VERSION = "1.3.4"
STYLE_VALUES = ["none", "ascii", "ascii2", "sharp", "rounded", "reinforced", "markdown", "grid"]
ALIGN_VALUES = ["left", "center", "right"]

HELP_TEMPLATE = """A high performance csv viewer with cjk/emoji support.

Usage: {prog} [OPTIONS] [FILE]

Arguments:
  [FILE]
          File to view

Options:
  -H, --no-headers
          Specify that the input has no header row
  -n, --number
          Prepend a column of line numbers to the table
  -t, --tsv
          Use '\\t' as delimiter for tsv
  -d, --delimiter <DELIMITER>
          Specify the field delimiter [default: ,]
  -s, --style <STYLE>
          Specify the border style [default: sharp] [possible values: none, ascii, ascii2, sharp,
          rounded, reinforced, markdown, grid]
  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]
  -i, --indent <INDENT>
          Specify global indent for table [default: 0]
      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify "0" to cancel limit
          [default: 1000]
      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]
      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left] [possible values: left, center,
          right]
  -P, --disable-pager
          Disable pager
  -h, --help
          Print help
  -V, --version
          Print version
"""

libc = ctypes.CDLL(None)
libc.wcwidth.argtypes = [ctypes.c_wchar]
libc.wcwidth.restype = ctypes.c_int


class CliExit(Exception):
    def __init__(self, code: int, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


class CsviewError(Exception):
    pass


class CsvShapeError(CsviewError):
    def __init__(self, record_index: int, line: int, byte_offset: int, fields: int, previous_fields: int) -> None:
        super().__init__(
            f"CSV error: record {record_index} (line: {line}, byte: {byte_offset}): "
            f"found record with {fields} fields, but the previous record has {previous_fields} fields"
        )


@dataclass
class Args:
    no_headers: bool = False
    number: bool = False
    tsv: bool = False
    delimiter: str = ","
    delimiter_explicit: bool = False
    style: str = "sharp"
    padding: int = 1
    indent: int = 0
    sniff: int = 1000
    header_align: str = "center"
    body_align: str = "left"
    disable_pager: bool = False
    file: Optional[str] = None


@dataclass(frozen=True)
class RuleStyle:
    left: str
    center: str
    right: str
    fill: str


@dataclass(frozen=True)
class RowStyle:
    left: str
    center: str
    right: str


SHORT_FLAGS = {"H", "n", "t", "P", "h", "V"}
SHORT_VALUE_OPTS = {"d", "s", "p", "i"}
LONG_FLAGS = {"no-headers", "number", "tsv", "disable-pager", "help", "version"}
LONG_VALUE_OPTS = {
    "delimiter",
    "style",
    "padding",
    "indent",
    "sniff",
    "header-align",
    "body-align",
}


def main(argv: Sequence[str]) -> int:
    prog = os.path.basename(sys.argv[0]) or "executable"
    try:
        args = parse_args(argv, prog)
        output = run(args)
        write_output(output, args.disable_pager)
        return 0
    except CliExit as exc:
        stream = sys.stdout if exc.code == 0 else sys.stderr
        stream.write(exc.message)
        if exc.message and not exc.message.endswith("\n"):
            stream.write("\n")
        return exc.code
    except CsviewError as exc:
        sys.stderr.write(f"csview: {exc}\n")
        return 1
    except OSError as exc:
        errno = exc.errno if exc.errno is not None else 0
        detail = exc.strerror or str(exc)
        sys.stderr.write(f"csview: {detail} (os error {errno})\n")
        return 1


def parse_args(argv: Sequence[str], prog: str) -> Args:
    args = Args()
    parsing_options = True
    idx = 0

    while idx < len(argv):
        token = argv[idx]

        if parsing_options and token == "--":
            parsing_options = False
            idx += 1
            continue

        if parsing_options and token.startswith("--") and token != "--":
            idx = parse_long_option(argv, idx, token, args, prog)
            continue

        if parsing_options and token.startswith("-") and token != "-":
            idx = parse_short_options(argv, idx, token, args, prog)
            continue

        if args.file is None:
            args.file = token
        else:
            raise CliExit(2, unexpected_argument_message(token, prog))
        idx += 1

    return args


def parse_long_option(argv: Sequence[str], idx: int, token: str, args: Args, prog: str) -> int:
    body = token[2:]
    if "=" in body:
        name, value = body.split("=", 1)
    else:
        name, value = body, None

    if name == "help":
        raise CliExit(0, help_text(prog))
    if name == "version":
        raise CliExit(0, version_text())

    if name in LONG_FLAGS:
        if value is not None:
            raise CliExit(2, unexpected_argument_message(f"--{name}", prog))
        apply_flag(name, args, prog)
        return idx + 1

    if name not in LONG_VALUE_OPTS:
        raise CliExit(2, unexpected_argument_message(f"--{name}", prog))

    if value is None:
        value, idx = next_option_value(argv, idx, canonical_option_display(name), prog)
    else:
        idx += 1

    apply_value(name, value, args, prog)
    return idx


def parse_short_options(argv: Sequence[str], idx: int, token: str, args: Args, prog: str) -> int:
    cluster = token[1:]
    pos = 0

    while pos < len(cluster):
        ch = cluster[pos]
        if ch == "h":
            raise CliExit(0, help_text(prog))
        if ch == "V":
            raise CliExit(0, version_text())
        if ch in SHORT_FLAGS:
            apply_short_flag(ch, args, prog)
            pos += 1
            continue
        if ch in SHORT_VALUE_OPTS:
            if pos + 1 < len(cluster):
                apply_short_value(ch, cluster[pos + 1 :], args, prog)
                return idx + 1
            value, next_idx = next_option_value(argv, idx, canonical_short_display(ch), prog)
            apply_short_value(ch, value, args, prog)
            return next_idx
        raise CliExit(2, unexpected_argument_message(f"-{ch}", prog))

    return idx + 1


def next_option_value(argv: Sequence[str], idx: int, opt_display: str, prog: str) -> Tuple[str, int]:
    if idx + 1 >= len(argv):
        raise CliExit(2, missing_value_message(opt_display))

    value = argv[idx + 1]
    if value == "--":
        raise CliExit(2, missing_value_message(opt_display))

    if value != "-" and value.startswith("-"):
        if looks_like_option(value):
            raise CliExit(2, missing_value_message(opt_display))
        raise CliExit(2, unexpected_argument_message(value, prog))

    return value, idx + 2


def looks_like_option(token: str) -> bool:
    if token.startswith("--"):
        name = token[2:].split("=", 1)[0]
        return name in LONG_FLAGS or name in LONG_VALUE_OPTS
    if token.startswith("-") and token != "-":
        return token[1] in SHORT_FLAGS or token[1] in SHORT_VALUE_OPTS
    return False


def apply_flag(name: str, args: Args, prog: str) -> None:
    if name == "no-headers":
        args.no_headers = True
    elif name == "number":
        args.number = True
    elif name == "tsv":
        if args.delimiter_explicit:
            raise CliExit(2, conflict_message("--tsv", "--delimiter <DELIMITER>", f"Usage: {prog} --tsv <FILE>"))
        args.tsv = True
    elif name == "disable-pager":
        args.disable_pager = True


def apply_short_flag(ch: str, args: Args, prog: str) -> None:
    mapping = {"H": "no-headers", "n": "number", "t": "tsv", "P": "disable-pager"}
    apply_flag(mapping[ch], args, prog)


def apply_value(name: str, value: str, args: Args, prog: str) -> None:
    if name == "delimiter":
        if args.tsv:
            raise CliExit(
                2,
                conflict_message("--delimiter <DELIMITER>", "--tsv", f"Usage: {prog} --delimiter <DELIMITER> <FILE>"),
            )
        args.delimiter = parse_delimiter(value)
        args.delimiter_explicit = True
        return
    if name == "style":
        args.style = parse_enum(value, STYLE_VALUES, "--style <STYLE>", True)
        return
    if name == "padding":
        args.padding = parse_usize(value, "--padding <PADDING>")
        return
    if name == "indent":
        args.indent = parse_usize(value, "--indent <INDENT>")
        return
    if name == "sniff":
        args.sniff = parse_usize(value, "--sniff <LIMIT>")
        return
    if name == "header-align":
        args.header_align = parse_enum(value, ALIGN_VALUES, "--header-align <HEADER_ALIGN>", False)
        return
    if name == "body-align":
        args.body_align = parse_enum(value, ALIGN_VALUES, "--body-align <BODY_ALIGN>", False)
        return
    raise AssertionError(name)


def apply_short_value(ch: str, value: str, args: Args, prog: str) -> None:
    mapping = {"d": "delimiter", "s": "style", "p": "padding", "i": "indent"}
    apply_value(mapping[ch], value, args, prog)


def parse_delimiter(value: str) -> str:
    if len(value) != 1:
        raise CliExit(2, invalid_value_message(value, "--delimiter <DELIMITER>", ": too many characters in string"))
    return value


def parse_usize(value: str, opt: str) -> int:
    if not value.isdigit():
        raise CliExit(2, invalid_value_message(value, opt, ": invalid digit found in string"))
    return int(value)


def parse_enum(value: str, allowed: Sequence[str], opt: str, suggest: bool) -> str:
    lowered = value.lower()
    if lowered in allowed:
        return lowered
    suggestion = None
    if suggest:
        matches = difflib.get_close_matches(lowered, list(allowed), n=1, cutoff=0.6)
        if matches:
            suggestion = matches[0]
    raise CliExit(2, invalid_enum_message(value, opt, allowed, suggestion))


def canonical_option_display(name: str) -> str:
    return {
        "delimiter": "--delimiter <DELIMITER>",
        "style": "--style <STYLE>",
        "padding": "--padding <PADDING>",
        "indent": "--indent <INDENT>",
        "sniff": "--sniff <LIMIT>",
        "header-align": "--header-align <HEADER_ALIGN>",
        "body-align": "--body-align <BODY_ALIGN>",
    }[name]


def canonical_short_display(ch: str) -> str:
    return {"d": "--delimiter <DELIMITER>", "s": "--style <STYLE>", "p": "--padding <PADDING>", "i": "--indent <INDENT>"}[ch]


def help_text(prog: str) -> str:
    return HELP_TEMPLATE.format(prog=prog)


def version_text() -> str:
    return f"csview {VERSION}\n"


def missing_value_message(opt: str) -> str:
    extra = ""
    if opt == "--style <STYLE>":
        extra = "\n  [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]"
    elif opt in ("--header-align <HEADER_ALIGN>", "--body-align <BODY_ALIGN>"):
        extra = "\n  [possible values: left, center, right]"
    return f"error: a value is required for '{opt}' but none was supplied{extra}\n\nFor more information, try '--help'."


def invalid_value_message(value: str, opt: str, reason: str) -> str:
    return f"error: invalid value '{value}' for '{opt}'{reason}\n\nFor more information, try '--help'."


def invalid_enum_message(value: str, opt: str, allowed: Sequence[str], suggestion: Optional[str]) -> str:
    parts = [
        f"error: invalid value '{value}' for '{opt}'",
        f"  [possible values: {', '.join(allowed)}]",
    ]
    if suggestion is not None:
        parts.extend(["", f"  tip: a similar value exists: '{suggestion}'"])
    parts.extend(["", "For more information, try '--help'."])
    return "\n".join(parts)


def unexpected_argument_message(arg: str, prog: str) -> str:
    parts = [f"error: unexpected argument '{arg}' found", ""]
    if arg.startswith("-"):
        parts.append(f"  tip: to pass '{arg}' as a value, use '-- {arg}'")
        parts.append("")
    parts.append(f"Usage: {prog} [OPTIONS] [FILE]")
    parts.append("")
    parts.append("For more information, try '--help'.")
    return "\n".join(parts)


def conflict_message(current: str, other: str, usage: str) -> str:
    return "\n".join(
        [
            f"error: the argument '{current}' cannot be used with '{other}'",
            "",
            usage,
            "",
            "For more information, try '--help'.",
        ]
    )


def run(args: Args) -> str:
    if args.file is None:
        data = sys.stdin.buffer.read()
    else:
        with open(args.file, "rb") as handle:
            data = handle.read()

    delimiter = 0x09 if args.tsv else (ord(args.delimiter[0]) & 0xFF)
    records = parse_records(data, delimiter)
    if args.no_headers:
        header = None
        body = records
    else:
        header = records[0] if records else []
        body = records[1:] if records else []

    if args.number:
        if header is not None:
            header = ["#"] + header
        body = [[str(index + 1)] + row for index, row in enumerate(body)]

    return render_table(args, header, body)


def parse_records(data: bytes, delimiter: int) -> List[List[str]]:
    records: List[List[str]] = []
    record: List[bytes] = []
    field = bytearray()
    record_index = 0
    previous_len: Optional[int] = None
    record_start_line = 1
    record_start_byte = 0
    line = 1
    in_quotes = False
    field_started = False
    record_touched = False
    i = 0

    def finish_record() -> None:
        nonlocal record, field, field_started, record_touched, previous_len, record_index
        if not record_touched and not field and not record:
            return
        record.append(bytes(field))
        field.clear()
        field_started = False
        if previous_len is not None and len(record) != previous_len:
            raise CsvShapeError(record_index, record_start_line, record_start_byte, len(record), previous_len)
        previous_len = len(record)
        records.append([decode_field(item) for item in record])
        record = []
        record_touched = False
        record_index += 1

    while i < len(data):
        byte = data[i]
        if in_quotes:
            if byte == 0x22:
                if i + 1 < len(data) and data[i + 1] == 0x22:
                    field.append(0x22)
                    i += 2
                    continue
                in_quotes = False
                i += 1
                continue
            field.append(byte)
            if byte == 0x0A:
                line += 1
            i += 1
            continue
        if byte == delimiter:
            record.append(bytes(field))
            field.clear()
            field_started = False
            record_touched = True
            i += 1
            continue
        if byte == 0x22 and not field_started:
            in_quotes = True
            field_started = True
            record_touched = True
            i += 1
            continue
        if byte in (0x0D, 0x0A):
            finish_record()
            field.clear()
            field_started = False
            record_touched = False
            if byte == 0x0D and i + 1 < len(data) and data[i + 1] == 0x0A:
                i += 2
            else:
                i += 1
            line += 1
            record_start_line = line
            record_start_byte = i
            continue
        field.append(byte)
        field_started = True
        record_touched = True
        i += 1

    if in_quotes:
        raise CsviewError("CSV error: EOF while inside quoted field")

    finish_record()
    return records


def decode_field(value: bytes) -> str:
    try:
        return value.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CsviewError(f"CSV error: invalid utf-8: {exc}") from exc


def render_table(args: Args, header: Optional[List[str]], body: List[List[str]]) -> str:
    widths = initial_widths(header, body, args.number, args.no_headers)
    if header is not None:
        update_widths(widths, header)
    sniff_limit = len(body) if args.sniff == 0 else min(len(body), args.sniff)
    for row in body[:sniff_limit]:
        update_widths(widths, row)

    lines: List[str] = []
    top = top_rule(args.style)
    middle = middle_rule(args.style)
    bottom = bottom_rule(args.style)

    if top is not None:
        lines.append(render_rule(widths, args.padding, top))
    if header is not None:
        lines.append(render_row(header, widths, args.padding, args.header_align, args.style))
        if body and middle is not None:
            lines.append(render_rule(widths, args.padding, middle))
    for index, row in enumerate(body):
        lines.append(render_row(row, widths, args.padding, args.body_align, args.style))
        if args.style == "grid" and index + 1 < len(body) and middle is not None:
            lines.append(render_rule(widths, args.padding, middle))
    if bottom is not None:
        lines.append(render_rule(widths, args.padding, bottom))

    if not lines:
        return ""
    indent = " " * args.indent
    return "\n".join(f"{indent}{line}" for line in lines) + "\n"


def initial_widths(header: Optional[List[str]], body: Sequence[Sequence[str]], number: bool, no_headers: bool) -> List[int]:
    if header is not None:
        return [0] * len(header)
    if body:
        return [0] * len(body[0])
    if number and no_headers:
        return [1]
    return []


def update_widths(widths: List[int], row: Sequence[str]) -> None:
    for index, value in enumerate(row):
        if index < len(widths):
            widths[index] = max(widths[index], display_width(value))


def display_width(value: str) -> int:
    return sum(char_width(ch) for ch in value)


def char_width(ch: str) -> int:
    width = libc.wcwidth(ch)
    return 1 if width < 0 else width


def truncate_to_width(value: str, limit: int) -> str:
    if display_width(value) <= limit:
        return value
    pieces: List[str] = []
    width = 0
    for ch in value:
        next_width = char_width(ch)
        if width + next_width > limit:
            break
        width += next_width
        pieces.append(ch)
    return "".join(pieces)


def format_cell(value: str, width: int, padding: int, align: str) -> str:
    clipped = truncate_to_width(value, width)
    slack = width - display_width(clipped)
    if align == "left":
        left_extra, right_extra = 0, slack
    elif align == "right":
        left_extra, right_extra = slack, 0
    else:
        left_extra = slack // 2
        right_extra = slack - left_extra
    return (" " * padding) + (" " * left_extra) + clipped + (" " * right_extra) + (" " * padding)


def render_row(row: Sequence[str], widths: Sequence[int], padding: int, align: str, style: str) -> str:
    parts = row_parts(style)
    cells = [format_cell(row[index] if index < len(row) else "", widths[index], padding, align) for index in range(len(widths))]
    return f"{parts.left}{parts.center.join(cells)}{parts.right}"


def render_rule(widths: Sequence[int], padding: int, style: RuleStyle) -> str:
    segments = [style.fill * (width + (padding * 2)) for width in widths]
    return f"{style.left}{style.center.join(segments)}{style.right}"


def row_parts(style: str) -> RowStyle:
    if style == "none":
        return RowStyle("", " ", "")
    if style == "ascii":
        return RowStyle("|", "|", "|")
    if style == "ascii2":
        return RowStyle(" ", "|", " ")
    if style == "markdown":
        return RowStyle("|", "|", "|")
    return RowStyle("│", "│", "│")


def top_rule(style: str) -> Optional[RuleStyle]:
    if style in {"none", "ascii2", "markdown"}:
        return None
    if style == "ascii":
        return RuleStyle("+", "+", "+", "-")
    if style in {"sharp", "grid"}:
        return RuleStyle("┌", "┬", "┐", "─")
    if style == "rounded":
        return RuleStyle("╭", "┬", "╮", "─")
    return RuleStyle("┏", "┬", "┓", "─")


def middle_rule(style: str) -> Optional[RuleStyle]:
    if style == "none":
        return None
    if style == "ascii":
        return RuleStyle("+", "+", "+", "-")
    if style == "ascii2":
        return RuleStyle(" ", "+", " ", "-")
    if style == "markdown":
        return RuleStyle("|", "|", "|", "-")
    return RuleStyle("├", "┼", "┤", "─")


def bottom_rule(style: str) -> Optional[RuleStyle]:
    if style in {"none", "ascii2", "markdown"}:
        return None
    if style == "ascii":
        return RuleStyle("+", "+", "+", "-")
    if style in {"sharp", "grid"}:
        return RuleStyle("└", "┴", "┘", "─")
    if style == "rounded":
        return RuleStyle("╰", "┴", "╯", "─")
    return RuleStyle("┗", "┴", "┛", "─")


def write_output(output: str, disable_pager: bool) -> None:
    if not disable_pager and sys.stdout.isatty():
        try:
            proc = subprocess.Popen(["less", "-SR"], stdin=subprocess.PIPE)
        except OSError:
            proc = None
        if proc is not None:
            try:
                if proc.stdin is not None:
                    proc.stdin.write(output.encode("utf-8"))
                    proc.stdin.close()
            except BrokenPipeError:
                pass
            proc.wait()
            return
    sys.stdout.write(output)
    sys.stdout.flush()


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
